{"kind":"tool","id":"WEaGeGQOdpY","toolName":"write_file","input":{"path":"src/index.css","instructions":"Global Tailwind styles, glassmorphism utilities and reduced-motion rules","content":"@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --accent-1: #22d3ee;
  --accent-2: #6366f1;
  --accent-3: #a855f7;
  color-scheme: dark;
}

@layer base {
  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }

  body {
    @apply bg-night-950 font-sans text-slate-200 antialiased;
    overflow-x: hidden;
    background-attachment: fixed;
  }

  ::selection {
    background: rgba(99, 102, 241, 0.4);
    color: #fff;
  }

  h1,
  h2,
  h3,
  h4 {
    @apply font-display;
    text-wrap: balance;
  }

  p {
    text-wrap: pretty;
  }

  /* Visible, consistent keyboard focus */
  :focus-visible {
    outline: 2px solid var(--accent-1);
    outline-offset: 3px;
    border-radius: 4px;
  }

  /* Custom slim scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #04040c;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--accent-2), var(--accent-3));
    border-radius: 999px;
    border: 2px solid #04040c;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, var(--accent-1), var(--accent-2));
  }
}

@layer components {
  /* Frosted glassmorphism surface */
  .glass {
    @apply border border-white/10 bg-white/[0.045] shadow-glass backdrop-blur-xl;
  }

  .glass-hover {
    @apply transition-all duration-300 hover:border-white/20 hover:bg-white/[0.07];
  }

  /* Gradient text */
  .text-gradient {
    @apply bg-clip-text text-transparent;
    background-image: linear-gradient(
      110deg,
      var(--accent-1),
      var(--accent-2) 45%,
      var(--accent-3)
    );
  }

  /* Gradient hairline border used on cards */
  .gradient-border {
    position: relative;
    background-clip: padding-box;
  }
  .gradient-border::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(
      135deg,
      rgba(34, 211, 238, 0.5),
      rgba(99, 102, 241, 0.25) 45%,
      rgba(168, 85, 247, 0.5)
    );
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
    opacity: 0.55;
    transition: opacity 0.35s ease;
  }
  .gradient-border:hover::before {
    opacity: 1;
  }

  .section-padding {
    @apply mx-auto w-full max-w-7xl px-5 py-24 sm:px-8 md:py-28 lg:px-10;
  }

  .eyebrow {
    @apply inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-1.5 font-mono text-xs uppercase tracking-[0.22em] text-neon-cyan;
  }

  .btn-primary {
    @apply relative inline-flex items-center justify-center gap-2 overflow-hidden rounded-full bg-accent-gradient px-7 py-3.5 font-semibold text-white shadow-glow transition-transform duration-300 hover:scale-[1.03] active:scale-[0.98];
  }

  .btn-ghost {
    @apply inline-flex items-center justify-center gap-2 rounded-full border border-white/15 bg-white/5 px-7 py-3.5 font-semibold text-slate-100 transition-all duration-300 hover:border-neon-cyan/60 hover:bg-white/10 hover:shadow-glow-cyan;
  }
}

/* Respect users who prefer less motion */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}
"}}
