/**
 * Detects low-powered / constrained devices so heavy 3D scenes can be
 * simplified or replaced with a lightweight CSS fallback.
 * Returns { isMobile, isLowPowered, reducedMotion }.
 */
export function useDeviceProfile() {
  const [profile, setProfile] = useState({
    isMobile: false,
    isLowPowered: false,
    reducedMotion: false,
    checked: false,
  });

  useEffect(() => {
    const compute = () => {
      const width = window.innerWidth;
      const coarse = window.matchMedia('(pointer: coarse)').matches;
      const reducedMotion = window.matchMedia(
        '(prefers-reduced-motion: reduce)'
      ).matches;

      const cores = navigator.hardwareConcurrency || 4;
      const memory = navigator.deviceMemory || 4; // GB, Chromium only
      const isMobile = coarse || width < 768;

      // Conservative heuristic: skip WebGL on phones and weak machines.
      const isLowPowered = isMobile || cores <= 4 || memory <= 4;

      setProfile({ isMobile, isLowPowered, reducedMotion, checked: true });
    };

    compute();
    window.addEventListener('resize', compute);
    return () => window.removeEventListener('resize', compute);
  }, []);

  return profile;
}
