{"kind":"tool","id":"WEgYII_ChyM","toolName":"write_file","input":{"path":"src/hooks/useScroll.js","instructions":"Page ready and scroll state hooks","content":"import { useEffect, useState } from 'react';

/** True once the page has finished its initial load. */
export function usePageReady(minDelay = 900) {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const started = performance.now();
    const finish = () => {
      const elapsed = performance.now() - started;
      const wait = Math.max(0, minDelay - elapsed);
      const timer = setTimeout(() => setReady(true), wait);
      return () => clearTimeout(timer);
    };

    if (document.readyState === 'complete') return finish();
    window.addEventListener('load', finish, { once: true });
    return () => window.removeEventListener('load', finish);
  }, [minDelay]);

  return ready;
}

/** Returns true once the user has scrolled past `threshold` pixels. */
export function useScrolled(threshold = 24) {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > threshold);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, [threshold]);

  return scrolled;
}
