/**
 * Lightweight 2D canvas starfield with drifting particles and twinkling
 * stars. Runs at ~40fps, pauses when the tab is hidden and renders a
 * single static frame when the user prefers reduced motion.
 */
export default function Starfield({ density = 0.00008 }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    const ctx = canvas.getContext('2d');
    let frameId = 0;
    let stars = [];
    let width = 0;
    let height = 0;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    const reducedMotion = window.matchMedia(
      '(prefers-reduced-motion: reduce)'
    ).matches;

    const buildStars = () => {
      const count = Math.min(220, Math.round(width * height * density));
      stars = Array.from({ length: count }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        r: Math.random() * 1.4 + 0.2,
        drift: Math.random() * 0.12 + 0.02,
        phase: Math.random() * Math.PI * 2,
        speed: Math.random() * 0.012 + 0.004,
        hue: Math.random() > 0.72 ? (Math.random() > 0.5 ? '34,211,238' : '168,85,247') : '226,232,240',
      }));
    };

    const resize = () => {
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      buildStars();
    };

    const draw = (t) => {
      ctx.clearRect(0, 0, width, height);
      for (const star of stars) {
        const alpha = 0.25 + 0.5 * (0.5 + 0.5 * Math.sin(t * star.speed + star.phase));
        ctx.beginPath();
        ctx.fillStyle = `rgba(${star.hue},${alpha})`;
        ctx.arc(star.x, star.y, star.r, 0, Math.PI * 2);
        ctx.fill();

        if (!reducedMotion) {
          star.y += star.drift;
          if (star.y > height + 2) {
            star.y = -2;
            star.x = Math.random() * width;
          }
        }
      }
    };

    const loop = (t) => {
      draw(t);
      frameId = window.requestAnimationFrame(loop);
    };

    resize();
    window.addEventListener('resize', resize);

    if (reducedMotion) {
      draw(0);
    } else {
      frameId = window.requestAnimationFrame(loop);
    }

    const onVisibility = () => {
      if (document.hidden) {
        window.cancelAnimationFrame(frameId);
      } else if (!reducedMotion) {
        frameId = window.requestAnimationFrame(loop);
      }
    };
    document.addEventListener('visibilitychange', onVisibility);

    return () => {
      window.cancelAnimationFrame(frameId);
      window.removeEventListener('resize', resize);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [density]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 z-0"
    />
  );
}
"}}


