import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';
import { getTechIcon } from '../utils/icons';

/**
 * A single skill tile with:
 *  - pointer-driven 3D tilt (rotateX / rotateY)
 *  - a cursor-following neon glow
 *  - graceful static behaviour on touch devices (no pointermove events)
 */
export default function SkillCard({ name, index = 0 }) {
  const ref = useRef(null);

  const mx = useMotionValue(0.5);
  const my = useMotionValue(0.5);

  const spring = { stiffness: 260, damping: 22, mass: 0.4 };
  const rotateX = useSpring(useTransform(my, [0, 1], [8, -8]), spring);
  const rotateY = useSpring(useTransform(mx, [0, 1], [-8, 8]), spring);
  const glowX = useTransform(mx, [0, 1], ['0%', '100%']);
  const glowY = useTransform(my, [0, 1], ['0%', '100%']);

  const { icon: Icon, color } = getTechIcon(name);

  const onPointerMove = (event) => {
    const node = ref.current;
    if (!node) return;
    const rect = node.getBoundingClientRect();
    mx.set((event.clientX - rect.left) / rect.width);
    my.set((event.clientY - rect.top) / rect.height);
  };

  const onPointerLeave = () => {
    mx.set(0.5);
    my.set(0.5);
  };

  return (
    <motion.article
      ref={ref}
      custom={index}
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-40px' }}
      transition={{ duration: 0.5, delay: Math.min(index * 0.05, 0.4) }}
      onPointerMove={onPointerMove}
      onPointerLeave={onPointerLeave}
      style={{ rotateX, rotateY, transformPerspective: 900 }}
      whileHover={{ scale: 1.05 }}
      className="group relative"
    >
      {/* Cursor-tracking glow */}
      <motion.span
        aria-hidden="true"
        style={{
          background: `radial-gradient(220px circle at ${glowX.get()} ${glowY.get()}, ${color}33, transparent 65%)`,
        }}
        className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-300 group-hover:opacity-100"
      />

      <div className="glass relative flex h-full flex-col items-center justify-center gap-3 rounded-2xl px-4 py-7 transition-all duration-300 group-hover:border-white/25 group-hover:shadow-glow">
        <span
          className="grid h-12 w-12 place-items-center rounded-xl border border-white/10 transition-transform duration-300 group-hover:scale-110"
          style={{ backgroundColor: `${color}1a`, color }}
        >
          <Icon size={22} aria-hidden="true" />
        </span>
        <h3 className="text-center font-display text-sm font-medium text-slate-200">
          {name}
        </h3>
      </div>
    </motion.article>
  );
}
