{"kind":"tool","id":"WFwJ11LKco0","toolName":"write_file","input":{"path":"src/components/BackToTop.jsx","instructions":"Floating back-to-top button and scroll progress bar","content":"import { useEffect, useState } from 'react';
import { motion, AnimatePresence, useScroll, useSpring } from 'framer-motion';
import { ArrowUp } from 'lucide-react';

/**
 * 1) Thin gradient scroll-progress bar pinned to the top of the viewport.
 * 2) Floating back-to-top button that appears after the first screen.
 */
export default function BackToTop({ onBackToTop }) {
  const [visible, setVisible] = useState(false);

  const { scrollYProgress } = useScroll();
  const progress = useSpring(scrollYProgress, {
    stiffness: 140,
    damping: 30,
    restDelta: 0.001,
  });

  useEffect(() => {
    const onScroll = () => setVisible(window.scrollY > 500);
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <>
      <motion.div
        aria-hidden="true"
        style={{ scaleX: progress }}
        className="fixed inset-x-0 top-0 z-[60] h-[3px] origin-left bg-accent-gradient"
      />

      <AnimatePresence>
        {visible ? (
          <motion.button
            type="button"
            onClick={onBackToTop}
            initial={{ opacity: 0, y: 20, scale: 0.85 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.85 }}
            transition={{ duration: 0.25, ease: 'easeOut' }}
            aria-label="Back to top"
            className="glass fixed bottom-6 right-5 z-50 grid h-12 w-12 place-items-center rounded-full text-slate-200 transition-colors duration-300 hover:border-neon-cyan/60 hover:text-neon-cyan hover:shadow-glow-cyan sm:bottom-8 sm:right-8"
          >
            <ArrowUp size={18} />
          </motion.button>
        ) : null}
      </AnimatePresence>
    </>
  );
}
"}}


